package com.tal.pocketflow;
import android.content.*;import android.app.*;import android.widget.*;import android.os.Looper;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import org.robolectric.shadows.*;import java.time.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class Upgrade012Test {
 Context c;Store s;Store.Account a;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.deleteDatabase("pocketflow.db");for(String key:new String[]{"prefs","security","google-drive","browser-sync"})c.getSharedPreferences(key,0).edit().clear().commit();s=new Store(c);a=new Store.Account();a.name="כרטיס";a.type="credit";a.closing=31;a.charge=10;a.start="2026-01-01";a.limit=1000000;s.save(a);}
 @After public void close(){s.close();}
 Store.Tx expense(String date,long amount,int count){Store.Tx t=new Store.Tx();t.kind="expense";t.date=date;t.amount=amount;t.originalAmount=amount;t.account=a.id;t.category="קניות";t.merchant="Amazon";t.tag="נוגה";t.note="משלוח";t.status=1;t.count=count;s.save(t);return t;}
 Store.Tx refund(Store.Tx parent,String date,long amount,int status){Store.Tx t=new Store.Tx();t.kind="refund";t.refundOf=parent.id;t.date=date;t.firstDue=Finance.due(LocalDate.parse(date),a.type,a.closing,a.charge).toString();t.amount=amount;t.originalAmount=amount;t.account=a.id;t.category=parent.category;t.merchant=parent.merchant;t.tag=parent.tag;t.note="החזר";t.count=1;t.status=status;s.save(t);return t;}
 @Test public void partialRefundReducesNetExpensesNotIncomeAndReleasesOnlyWhenPosted(){Store.Tx t=expense("2026-10-15",30000,1);refund(t,"2026-10-20",8000,1);assertEquals(30000,s.creditUsage(a,LocalDate.parse("2026-10-19")));assertEquals(22000,s.creditUsage(a,LocalDate.parse("2026-10-20")));assertEquals(22000,s.overview(YearMonth.of(2026,10)).total());assertEquals(0,s.total(YearMonth.of(2026,10),"income"));assertEquals(22000,s.charges(YearMonth.of(2026,11)).stream().mapToLong(x->x.amount).sum());assertEquals(0,s.creditUsage(a,LocalDate.parse("2026-11-10")));assertEquals(22000,new Analytics(s,c).spend(YearMonth.of(2026,10),"קניות"));}
 @Test public void pendingRefundDoesNotReleaseCreditAndCannotOverRefundOrDeletePurchase(){Store.Tx t=expense("2026-10-15",30000,1);refund(t,"2026-10-20",8000,0);assertEquals(30000,s.creditUsage(a,LocalDate.parse("2026-10-20")));try{refund(t,"2026-10-22",23000,1);fail();}catch(IllegalArgumentException expected){}try{s.remove(t);fail();}catch(IllegalArgumentException expected){}assertEquals(2,s.transactions().size());}
 @Test public void fullRefundForInstallmentsRetainsScheduleAndOffsetsFutureBill(){Store.Tx t=expense("2026-10-01",60000,3);refund(t,"2026-10-20",60000,1);assertEquals(0,s.creditUsage(a,LocalDate.parse("2026-10-20")));assertEquals(-40000,s.charges(YearMonth.of(2026,11)).stream().mapToLong(x->x.amount).sum());assertEquals(20000,s.charges(YearMonth.of(2026,12)).stream().mapToLong(x->x.amount).sum());assertEquals(40000,s.creditUsage(a,LocalDate.parse("2026-11-10")));}
 @Test public void lateMonthRefundCountsInReceiptMonthAndBackupRoundTrips()throws Exception{Store.Tx t=expense("2026-09-15",30000,1);refund(t,"2026-10-20",8000,1);assertEquals(30000,s.total(YearMonth.of(2026,9),"expense"));assertEquals(-8000,s.total(YearMonth.of(2026,10),"expense"));JSONObject b=s.backup();assertEquals(9,b.getInt("version"));s.restore(b);assertEquals(t.id,s.transactions().get(0).refundOf);JSONObject invalid=s.backup();invalid.getJSONArray("transactions").getJSONObject(1).put("refund_of",999999);try{s.restore(invalid);fail();}catch(Exception expected){}assertEquals(2,s.transactions().size());assertEquals(-8000,s.overview(YearMonth.of(2026,10)).total());}
 @Test public void fixedCycleRefundFreesFrameAndReducesEligiblePayment(){a.type="fixed";a.payment=50000;a.cycleConfigured=true;a.closing=9;s.save(a);Store.Tx t=expense("2026-10-12",60000,3);refund(t,"2026-10-20",60000,1);assertEquals(0,s.creditUsage(a,LocalDate.parse("2026-10-20")));assertEquals(0,s.charges(YearMonth.of(2026,11)).stream().mapToLong(x->x.amount).sum());}
 @Test public void undoDeletionEditAndPreferencesIsOneStepAndAtomic()throws Exception{Store.Tx t=expense("2026-10-15",30000,1);s.edit("מחיקה",()->s.remove(t));assertTrue(s.transactions().isEmpty());s.undo();assertEquals(30000,s.transaction(t.id).amount);assertEquals("",s.undoLabel());s.edit("עריכה",()->{Store.Tx x=s.transaction(t.id);x.amount=20000;s.save(x);});s.close();s=new Store(c);s.undo();assertEquals(30000,s.transaction(t.id).amount);s.edit("תקציב",()->Tools.write(c,new JSONObject().put("budgets",new JSONObject().put("",10000)),false));assertEquals(10000,Tools.budgets(c).getLong(""));s.undo();assertEquals(0,Tools.budgets(c).length());try{s.edit("כשל",()->{Store.Tx x=s.transaction(t.id);x.amount=100;s.save(x);throw new Exception("כשל");});fail();}catch(Exception expected){}assertEquals(30000,s.transaction(t.id).amount);}
 @Test public void undoRuleChangeRestoresOriginalOccurrences()throws Exception{Store.Rule r=new Store.Rule();r.name="מנוי";r.amount=1000;r.category="חשבונות";r.account=a.id;r.start="2026-01-01";r.end="";r.active=1;s.save(r);s.ensureMonth(YearMonth.of(2026,3));s.edit("עדכון",()->{r.amount=2000;s.updateRule(r,YearMonth.of(2026,3));});assertEquals(6000,s.transactions().stream().mapToLong(x->x.amount).sum());s.undo();assertEquals(1000,s.rules().get(0).amount);assertEquals(3000,s.transactions().stream().mapToLong(x->x.amount).sum());}
 @Test public void cachesDoNotExposeMutableObjectsAndSeeOtherStoreWrites(){Store.Tx t=expense("2026-10-15",30000,1);List<Store.Tx> returned=s.transactions();returned.get(0).amount=1;assertEquals(30000,s.transaction(t.id).amount);try(Store other=new Store(c)){Store.Tx x=other.transaction(t.id);x.amount=25000;other.save(x);}assertEquals(25000,s.transaction(t.id).amount);s.account(a.id).name="שונה";assertEquals("כרטיס",s.account(a.id).name);}
 @Test public void filtersCombineDatesAmountsFamilyAccountStatusAndTokensAndRoundTrip(){Store.Tx t=expense("2026-10-15",30000,1);MovementFilter f=new MovementFilter();f.from="2026-09-01";f.to="2026-11-30";f.family="נוגה";f.min=10000;f.max=40000;f.status=1;f.kind="expense";f=MovementFilter.from(f.json());assertTrue(f.matches(t,YearMonth.of(2026,11),"קניות",a.id,"Amazon","amazon משלוח"));assertFalse(f.matches(t,YearMonth.of(2026,11),"קניות",a.id,"Amazon","לא קיים"));f.min=31000;assertFalse(f.matches(t,YearMonth.of(2026,11),"",0,"",""));try{f.from="2027-01-01";f.validate();fail();}catch(IllegalArgumentException expected){}}
 @Test public void uiCreatesRefundAndOffersUndoWithExistingData()throws Exception{Store.Tx t=expense(LocalDate.now().toString(),30000,1);try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity main=controller.get();StoreTest.navigate(main,1);java.lang.reflect.Method open=MainActivity.class.getDeclaredMethod("refundDialog",Store.Tx.class,Store.Tx.class);open.setAccessible(true);open.invoke(main,t,null);Shadows.shadowOf(Looper.getMainLooper()).idle();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();((EditText)d.getWindow().getDecorView().findViewWithTag("סכום הזיכוי בשקלים")).setText("80");d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertFalse(ShadowToast.getTextOfLatestToast(),d.isShowing());assertEquals(2,s.transactions().size());main.getWindow().getDecorView().findViewWithTag("undo-last").performClick();assertEquals(1,s.transactions().size());assertEquals(30000,s.transactions().get(0).amount);}}
 @Test public void refundWithPolicyHistoryKeepsPastBillingAndDoesNotBecomeIncome(){a.opening=100000;s.save(a);Store.Tx t=expense("2026-10-15",30000,1);a.type="fixed";a.payment=50000;s.save(a,LocalDate.parse("2026-11-01"));long historical=s.creditUsage(a,LocalDate.parse("2026-10-25"));refund(t,"2026-11-03",8000,1);assertEquals(historical,s.creditUsage(a,LocalDate.parse("2026-10-25")));assertEquals(122000,s.creditUsage(a,LocalDate.parse("2026-11-03")));assertEquals(72000,s.creditUsage(a,LocalDate.parse("2026-11-10")));assertEquals(50000,s.charges(YearMonth.of(2026,11)).stream().mapToLong(x->x.amount).sum());assertEquals(0,s.total(YearMonth.of(2026,11),"income"));}
 @Test public void refundsForRecurringChargesRemainInRecurringSubtotal(){Store.Rule r=new Store.Rule();r.name="מנוי";r.amount=10000;r.account=a.id;r.category="חשבונות";r.start="2026-10-01";r.end="";r.active=1;s.save(r);s.ensureMonth(YearMonth.of(2026,10));Store.Tx t=s.transactions().get(0);t.status=1;s.save(t);refund(t,"2026-10-20",2000,1);Store.Overview o=s.overview(YearMonth.of(2026,10));assertEquals(8000,o.recurring);assertEquals(0,o.occasional);assertEquals(0,new Analytics(s,c).variableAverage(YearMonth.of(2026,11)));}
 @Test public void savedSearchSurvivesBackupAndUndoRestoresDeletedSearch()throws Exception{MovementFilter f=new MovementFilter();f.from="2026-09-01";f.family="נוגה";JSONObject search=f.json().put("name","נוגה ברבעון").put("account",a.id);Tools.write(c,new JSONObject().put("searches",new JSONArray().put(search)),false);JSONObject backup=s.backup();s.restore(backup);assertEquals("נוגה",Tools.read(c).getJSONArray("searches").getJSONObject(0).getString("family"));s.edit("מחיקת חיפוש",()->Tools.write(c,new JSONObject(),false));s.undo();assertEquals(1,Tools.read(c).getJSONArray("searches").length());}
 @Test @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE) @Config(qualifiers="he-rIL-w411dp-h891dp-xxhdpi") public void renderRefundAndAdvancedSearchScreens()throws Exception{Store.Tx t=expense(LocalDate.now().toString(),30000,1);try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity main=controller.get();java.lang.reflect.Method open=MainActivity.class.getDeclaredMethod("refundDialog",Store.Tx.class,Store.Tx.class);open.setAccessible(true);open.invoke(main,t,null);Shadows.shadowOf(Looper.getMainLooper()).idle();snapshot(ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView(),"refund-012");ShadowAlertDialog.getLatestAlertDialog().dismiss();StoreTest.navigate(main,1);snapshot(main.getWindow().getDecorView(),"movements-012");java.lang.reflect.Method advanced=MainActivity.class.getDeclaredMethod("advancedSearchDialog");advanced.setAccessible(true);advanced.invoke(main);Shadows.shadowOf(Looper.getMainLooper()).idle();snapshot(ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView(),"filters-012");}}
 void snapshot(android.view.View v,String name)throws Exception{v.measure(android.view.View.MeasureSpec.makeMeasureSpec(1080,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(1920,android.view.View.MeasureSpec.EXACTLY));v.layout(0,0,1080,1920);android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(1080,1920,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(image));java.io.File dir=new java.io.File("build/design-previews");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){assertTrue(image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}image.recycle();}

 @Test public void deletingSavedSearchClosesMenuAndCanBeUndone()throws Exception{JSONObject q=new MovementFilter().json().put("name","חיפוש אישי");Tools.write(c,new JSONObject().put("searches",new JSONArray().put(q)),false);try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=controller.get();StoreTest.navigate(a,1);java.lang.reflect.Method show=MainActivity.class.getDeclaredMethod("savedSearchDialog");show.setAccessible(true);show.invoke(a);Shadows.shadowOf(Looper.getMainLooper()).idle();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();StoreTest.find(d.getWindow().getDecorView(),"מחיקת החיפוש").performClick();assertFalse(d.isShowing());assertEquals(0,Tools.read(c).getJSONArray("searches").length());a.getWindow().getDecorView().findViewWithTag("undo-last").performClick();assertEquals(1,Tools.read(c).getJSONArray("searches").length());}}

}
